/// How long one status change may take to fan out: a backstop under the
/// function's hard 10 s timeout, so that whatever is still pending is
/// recorded before the runtime abandons the invocation.
pub const DISPATCH_BUDGET: Duration = Duration::from_secs(8);

/// How long one webhook call may take, connecting included.
pub const CALL_TIMEOUT: Duration = Duration::from_secs(5);

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// The platform's health receiver, reached over the same egress as relying
/// parties; it answers 200 to every status event (PI-STD-014).
pub const CANARY_URL: &str = "https://canary.status.membership-platform.example/webhooks/status";

