cat >> tests/callbacks.rs <<'EOF'

// --- every outcome is recorded, inside the platform's limit ----------------

#[tokio::test(start_paused = true)]
async fn a_silent_subscriber_is_recorded_as_failed_within_the_call_bound() {
    let rig = rig();
    rig.subscriber("a-silent", Endpoint::Hang);
    rig.subscriber("b-healthy", Endpoint::ok());

    let started = Instant::now();
    rig.revoke().await;

    assert!(started.elapsed() < DISPATCH_BUDGET, "fan-out took {:?}", started.elapsed());
    let failures = rig.failures("a-silent");
    assert!(failures.len() == 1 && failures[0].contains("no response"), "recorded for a-silent: {failures:?}");
}

/// Enough silent subscribers that the lookup (110 pages) plus one call bound
/// runs past the platform's timeout.
fn overrun_rig() -> (Rig, Vec<String>) {
    let rig = rig();
    let ids = rig.subscribers_on_one_host("silent", 11_000, Endpoint::Hang);
    (rig, ids)
}

#[tokio::test(start_paused = true)]
async fn the_fan_out_ends_before_the_platform_kills_it() {
    let (rig, _) = overrun_rig();

    let started = Instant::now();
    rig.revoke().await;

    assert!(started.elapsed() < PLATFORM_TIMEOUT, "fan-out ran {:?}; the runtime abandons it at {PLATFORM_TIMEOUT:?}", started.elapsed());
}

#[tokio::test(start_paused = true)]
async fn subscribers_still_pending_when_the_budget_runs_out_are_recorded_as_failed() {
    let (rig, ids) = overrun_rig();

    rig.revoke().await;

    let events = rig.sink.events();
    let unrecorded = ids.iter().filter(|id| !events.iter().any(|e| &e.subscription == *id)).count();
    assert_eq!(unrecorded, 0, "{unrecorded} of {} subscribers have no recorded outcome", ids.len());
    assert!(rig.failures(&ids[0]).iter().all(|r| r.contains("within")), "{:?}", rig.failures(&ids[0]));
}

// --- the health check ---------------------------------------------------------

/// So many subscriptions that the index lookup alone (170 pages) outlasts
/// the budget: nothing reaches anyone.
fn lookup_overrun(rig: &Rig) {
    rig.subscribers_on_one_host("never-reached", 17_000, Endpoint::ok());
}

#[tokio::test(start_paused = true)]
async fn the_health_check_is_not_green_when_the_lookup_does_not_finish() {
    let rig = rig();
    lookup_overrun(&rig);

    rig.revoke().await;

    assert!(!rig.notifier.canary_healthy(), "health check green although no subscriber was reached");
    assert!(!rig.failures(CANARY_ID).is_empty(), "the canary's missed delivery is not recorded");
}

#[tokio::test(start_paused = true)]
async fn the_health_check_does_not_carry_over_from_the_previous_change() {
    let rig = rig();
    rig.revoke().await;
    assert!(rig.notifier.canary_healthy(), "precondition: the first change reached the canary");

    lookup_overrun(&rig);
    rig.revoke().await;

