/// Sends `change` to the platform subscribers and to every subscriber of
/// the issuing tenant, all at once, and records every outcome.
pub async fn notify(&self, change: &StatusChange) {
    let tenant = change.issuer.as_str();
    let body = payload(change);
    self.canary_ok.store(false, Ordering::SeqCst);

    // Subscribers whose outcome is not recorded yet, by position.
    let pending: Mutex<BTreeMap<usize, Subscription>> = Mutex::new(self.platform.iter().cloned().enumerate().collect());

    let fan_out = async {
        let subscribers: Vec<Subscription> =
            self.platform.iter().cloned().chain(self.subscriptions(tenant).await).collect();
        pending.lock().unwrap().extend(subscribers.iter().cloned().enumerate());
        let mut calls: Vec<_> = subscribers
            .iter()
            .enumerate()
            .map(|(position, sub)| Box::pin(self.dispatch(tenant, position, sub, &body, &pending)))
            .collect();
        poll_fn(|cx| {
            calls.retain_mut(|call| call.as_mut().poll(cx).is_pending());
            if calls.is_empty() { Poll::Ready(()) } else { Poll::Pending }
        })
        .await;
    };

    if tokio::time::timeout(DISPATCH_BUDGET, fan_out).await.is_err() {
        eprintln!("notifier: {tenant}: fan-out for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
        let reason = format!("not delivered within {DISPATCH_BUDGET:?}");
        for (_, sub) in std::mem::take(&mut *pending.lock().unwrap()) {
            self.record(tenant, &sub, Outcome::Failed { reason: reason.clone() });
        }
    }
}

/// The tenant's webhook subscriptions, through the `tenant-kind` index.
async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
    self.settings.query_kind(tenant, WEBHOOK_KIND).await.iter().filter_map(Subscription::from_setting).collect()
}

/// POSTs `body` to the subscriber at `position`, bounded by
/// [`CALL_TIMEOUT`], and records the outcome.
async fn dispatch(
    &self,
    tenant: &str,
    position: usize,
    sub: &Subscription,
    body: &[u8],
    pending: &Mutex<BTreeMap<usize, Subscription>>,
) {
    let outcome = match tokio::time::timeout(CALL_TIMEOUT, self.transport.post(&sub.url, body)).await {
        Ok(Ok(status)) if (200..300).contains(&status) => Outcome::Delivered { status },
        Ok(Ok(status)) => Outcome::Failed { reason: format!("HTTP {status}") },
        Ok(Err(error)) => Outcome::Failed { reason: error.to_string() },
        Err(_) => Outcome::Failed { reason: format!("no response within {CALL_TIMEOUT:?}") },
    };
    if position < self.platform.len() && sub.id == CANARY_ID {
        self.canary_ok.store(matches!(outcome, Outcome::Delivered { .. }), Ordering::SeqCst);

